import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value, uint256 initialBalance) public {
        // Constrain to admissible domain: owner can only withdraw up to contract balance
        vm.assume(initialBalance >= _value);
        vm.assume(initialBalance > 0);
        vm.assume(_value > 0);
        // Fund the contract
        vm.deal(address(c), initialBalance);
        uint256 balanceBefore = address(c).balance;
        // Owner calls withdraw
        vm.prank(c.owner());
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", _value));
        if (!ok) {
            // If it reverted, balance should be unchanged; skip assertion for this branch
            return;
        }
        uint256 balanceAfter = address(c).balance;
        // Rule: a successful withdraw must have decreased the balance by at least _value
        // (exactly _value in the correct contract; bug transfers nothing so decrease is 0)
        assertTrue(balanceBefore - balanceAfter >= _value);
    }
}

