pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 seed) public {
        // Bound value to something the contract can pay (we'll fund it)
        value = bound(value, 1, 100 ether);
        // Fund the owner (default sender) so they can fund the contract
        address owner = c.owner();
        vm.deal(owner, 200 ether);
        // Send value to the contract via fallback to give it balance, so sendMoney can transfer out
        vm.prank(owner);
        (bool fundOk,) = address(c).call{value: value}();
        assertTrue(fundOk, "funding failed");

        // Deploy an adversarial contract that reverts on receiving ETH via transfer (2300 gas)
        // but succeeds with call (more gas). The fuzz seed determines if we use the adversarial contract
        // or a plain EOA, ensuring the fuzzer explores both scenarios.
        address target;
        if (seed % 2 == 0) {
            target = address(new Reverter());
        } else {
            target = address(uint160(seed | 0xFF)); // arbitrary EOA
        }

        // Record recipient balance before
        uint256 beforeBal = target.balance;
        // Owner calls sendMoney
        vm.prank(owner);
        (bool success,) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));
        // For the reference, the call sends ETH; for the mutant, transfer may fail silently (return false)
        // The invariant: the recipient's balance MUST increase by exactly `value` if the call succeeded.
        // If success is false, the state shouldn't change (but re-entrancy isn't a concern here).
        if (success) {
            assertEq(target.balance - beforeBal, value, "recipient balance must increase by value on success");
        } else {
            // If the call reverted, balance shouldn't change
            assertEq(target.balance, beforeBal, "recipient balance unchanged on revert");
        }
    }
}

contract Reverter {
    fallback() external payable {
        // Uses more than 2300 gas so transfer fails but call succeeds
        uint256 x = 0;
        for (uint256 i = 0; i < 100; i++) {
            x++;
        }
    }
}

