pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value, address _target) public {
        // Restrict _value to avoid overflow and ensure contract has enough balance
        _value = bound(_value, 0, address(c).balance);
        // Ensure _target is not the contract itself to avoid selfdestruct-like edge cases
        vm.assume(_target != address(c));
        // Record initial balances
        uint256 initialContractBalance = address(c).balance;
        uint256 initialOwnerBalance = c.owner().balance;
        // Execute the transaction as owner
        vm.prank(c.owner());
        c.sendMoney(_target, _value);
        // Calculate observed change in the sum of contract and owner balances
        uint256 finalContractBalance = address(c).balance;
        uint256 finalOwnerBalance = c.owner().balance;
        uint256 sumDelta = (initialContractBalance + initialOwnerBalance) - (finalContractBalance + finalOwnerBalance);
        // The sum should decrease by exactly _value
        assertTrue(sumDelta == _value);
    }
}
